// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(string memory expectedVersion) public {
        vm.assume(keccak256(bytes(expectedVersion)) == keccak256(bytes("1.0.0")));
        string memory actualVersion = c.version();
        assertTrue(keccak256(bytes(actualVersion)) == keccak256(bytes(expectedVersion)));
    }
}
